import { scanPages } from "./core/scanner";
import { generateRouter } from "./core/generator";
import { RouterWriter } from "./writers/types";

export interface RouterMapperConfig {
    pages: {
        dir: string;
        extensions?: string[];
    };
    output: {
        dir: string;
        fileName?: string;
    };
    writer: RouterWriter;
    importBase?: string;
}

export function routerMapper(config: RouterMapperConfig): void {
    const files = scanPages(
        config.pages.dir,
        config.pages.extensions ?? [".tsx", ".ts"]
    );

    const routes = generateRouter(files);

    config.writer.write(routes, {
        outputDir: config.output.dir,
        fileName: config.output.fileName ?? "router",
        importBase: config.importBase ?? "../../pages",
        pagesDir: config.pages.dir
    });
}
