import { mkdirSync, writeFileSync } from "fs";
import { join } from "path";
import { RouterWriter, WriterOptions } from "./types";
import { normalizeImportPath, toRoutePath } from "../utils/path";

export function reactRouterWriter(): RouterWriter {
    return {
        write(routes, options: WriterOptions) {
            const { outputDir, fileName, importBase, pagesDir } = options;

            mkdirSync(outputDir, { recursive: true });

            const generateRouteBlock = (r: { file: string; path: string }) =>
                [
                    `  {`,
                    `    path: "${toRoutePath(r.file, pagesDir)}",`,
                    `    component: lazy(() => import(/* @vite-ignore */ "${importBase}/${normalizeImportPath(r.file)}"))`,
                    `  }`
                ].join("\n");

            const content = [
                "// This file is auto-generated by rakit-routes",
                "// Do not edit this file manually",
                "",
                'import { lazy } from "react";',
                "const router = [",
                routes.map(generateRouteBlock).join(",\n"),
                "];",
                "export default router;",
                ""
            ].join("\n");

            const filePath = join(outputDir, `${fileName}.tsx`);

            writeFileSync(filePath, content, { encoding: "utf-8" });

            console.log(`✔ Router file generated at: ${filePath}`);
        }
    };
}
